//! Branch protection → land rules in `.beehive/policy.toml`, and CODEOWNERS → owners
//! (SPEC §17.2). The generated file is shown for review, never landed silently; anything
//! without a bee equivalent is listed as [`Untranslatable`] in the fidelity report.
//!
//! | GitHub | `.beehive/policy.toml` |
//! |---|---|
//! | branch name or `prefix*` pattern | `[[land]] ref` (a `*` that GitHub would stop at `/` covers deeper refs too: reported) |
//! | required status checks | `required_checks` (GitHub's "up to date" is what land does anyway: it lands onto the tip) |
//! | required approving reviews | `[[land.approvals]] count`; code-owner reviews → `from = "owners"` |
//! | dismiss stale reviews | `dismiss_stale_approvals` |
//! | require approval of the most recent push | `require_last_push_approval` |
//! | required signatures / linear history | `require_signed` / `require_linear` |
//! | push restrictions (users, teams) | `allow` (placeholder principal ids, `@org/team`) |
//! | lock branch | `allow = []` |
//! | deletions / creations blocked | `[[refs]] delete = []` / `create = []` |
//! | force pushes blocked | nothing to write: protected refs move only through Land |
//!
//! Not translated (reported): force pushes allowed, admins exempt (`enforce_admins` off),
//! conversation resolution, required deployments, app push restrictions, review dismissal
//! and bypass allowances, glob patterns other than a trailing `*`.
//!
//! The output is validated with `bee-policy`'s parser before it is returned.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::model::{Protection, Restrictions};
use crate::principals::Directory;
use crate::report::Untranslatable;

/// Where GitHub looks for CODEOWNERS, in its order.
pub const CODEOWNERS_PATHS: [&str; 3] = [".github/CODEOWNERS", "CODEOWNERS", "docs/CODEOWNERS"];

/// The result of translating one repository's settings.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Translation {
    /// The generated `.beehive/policy.toml`.
    pub toml: String,
    /// Branch patterns translated (possibly with notes).
    pub translated: Vec<String>,
    /// Branch patterns not translated at all.
    pub skipped: Vec<String>,
    /// Settings that were not translated, with what to do.
    pub untranslatable: Vec<Untranslatable>,
    /// The CODEOWNERS file referenced, if any.
    pub codeowners: Option<String>,
    /// CODEOWNERS lines bee accepts.
    pub codeowners_rules: u64,
}

fn q(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn list(items: &[String]) -> String {
    let v: Vec<String> = items.iter().map(|s| q(s)).collect();
    format!("[{}]", v.join(", "))
}

/// The bee ref pattern for a GitHub branch pattern, and whether it widens the match.
/// `None` when it cannot be expressed.
pub fn ref_pattern(github: &str) -> Option<(String, bool)> {
    let globby = |s: &str| s.contains(['*', '?', '[', ']', '{', '}', '\\']);
    if !globby(github) {
        return Some((github.to_string(), false));
    }
    let stem = github.strip_suffix('*')?;
    if globby(stem) {
        return None;
    }
    // GitHub's `*` stops at `/`; bee's prefix pattern does not. `*` alone already covers
    // every branch in both.
    Some((github.to_string(), !stem.is_empty()))
}

fn subjects(r: &Restrictions, dir: &mut Directory, org: &str) -> Vec<String> {
    let mut v: Vec<String> = r.users.iter().map(|u| dir.of(u).principal).collect();
    v.extend(r.teams.iter().map(|t| format!("@{org}/{}", t.slug)));
    v.sort();
    v.dedup();
    v
}

/// Translates branch protection (by pattern) and the CODEOWNERS file found in the
/// repository (`codeowners`: its path and text).
pub fn translate(
    repo_full_name: &str,
    protections: &BTreeMap<String, Protection>,
    codeowners: Option<(&str, &str)>,
    dir: &mut Directory,
) -> Translation {
    let org = repo_full_name.split('/').next().unwrap_or("");
    let mut t = Translation::default();
    let mut out = String::new();
    let _ = writeln!(
        out,
        "# Generated by bee-github from the GitHub settings of {repo_full_name}.\n\
         # Review before landing; the fidelity report lists what was not translated."
    );
    let _ = writeln!(out, "version = 1");
    if let Some((path, text)) = codeowners {
        let _ = writeln!(out, "codeowners = {}", q(path));
        t.codeowners = Some(path.to_string());
        for (i, line) in text.lines().enumerate() {
            let l = line.trim();
            if l.is_empty() || l.starts_with('#') {
                continue;
            }
            match bee_policy::Codeowners::parse(l) {
                Ok(_) => t.codeowners_rules += 1,
                Err(e) => t.untranslatable.push(Untranslatable {
                    setting: "codeowners.line".into(),
                    item: format!("{path}:{}", i + 1),
                    detail: format!("{e}; this line is ignored by bee, rewrite it"),
                }),
            }
        }
    }
    let mut refs_rules = String::new();
    for (pattern, p) in protections {
        let note = |t: &mut Translation, setting: &str, detail: &str| {
            t.untranslatable.push(Untranslatable {
                setting: format!("branch_protection.{setting}"),
                item: pattern.clone(),
                detail: detail.to_string(),
            });
        };
        let Some((pat, widened)) = ref_pattern(pattern) else {
            note(
                &mut t,
                "pattern",
                "bee ref patterns are an exact name or a prefix ending in one `*`; write a rule per branch",
            );
            t.skipped.push(pattern.clone());
            continue;
        };
        if widened {
            note(
                &mut t,
                "pattern",
                "GitHub's `*` stops at `/`; the bee prefix also covers deeper refs, so the rule protects more",
            );
        }
        let _ = writeln!(out, "\n[[land]]\nref = {}", q(&pat));
        if p.lock_branch.as_ref().is_some_and(|e| e.enabled) {
            let _ = writeln!(out, "allow = []");
        } else if let Some(r) = &p.restrictions {
            let s = subjects(r, dir, org);
            let _ = writeln!(out, "allow = {}", list(&s));
            if !r.apps.is_empty() {
                note(
                    &mut t,
                    "restrictions.apps",
                    "GitHub Apps allowed to push have no principal yet; add their agent principals to `allow`",
                );
            }
        }
        if let Some(sc) = &p.required_status_checks {
            let mut checks: Vec<String> = sc.contexts.clone();
            checks.extend(sc.checks.iter().map(|c| c.context.clone()));
            checks.sort();
            checks.dedup();
            if !checks.is_empty() {
                let _ = writeln!(out, "required_checks = {}", list(&checks));
            }
            if sc.checks.iter().any(|c| c.app_id.is_some()) {
                note(
                    &mut t,
                    "required_status_checks.app_id",
                    "checks are required by name; the reporting app is not pinned",
                );
            }
        }
        let on = |e: &Option<crate::model::Enabled>| e.as_ref().is_some_and(|e| e.enabled);
        if on(&p.required_signatures) {
            let _ = writeln!(out, "require_signed = true");
        }
        if on(&p.required_linear_history) {
            let _ = writeln!(out, "require_linear = true");
        }
        if let Some(rv) = &p.required_pull_request_reviews {
            if rv.dismiss_stale_reviews {
                let _ = writeln!(out, "dismiss_stale_approvals = true");
            }
            if rv.require_last_push_approval {
                let _ = writeln!(out, "require_last_push_approval = true");
            }
            if rv.required_approving_review_count > 0 || rv.require_code_owner_reviews {
                let _ = writeln!(out, "\n[[land.approvals]]");
                let _ = writeln!(out, "count = {}", rv.required_approving_review_count.max(1));
                if rv.require_code_owner_reviews {
                    let _ = writeln!(out, "from = \"owners\"");
                }
            }
            if rv
                .dismissal_restrictions
                .as_ref()
                .is_some_and(|d| !d.users.is_empty() || !d.teams.is_empty())
            {
                note(
                    &mut t,
                    "required_pull_request_reviews.dismissal_restrictions",
                    "who may dismiss reviews is governed by the review role in bee",
                );
            }
            if rv
                .bypass_pull_request_allowances
                .as_ref()
                .is_some_and(|d| !d.users.is_empty() || !d.teams.is_empty() || !d.apps.is_empty())
            {
                note(
                    &mut t,
                    "required_pull_request_reviews.bypass_pull_request_allowances",
                    "add a ruleset with `bypass` for these principals if they must skip reviews",
                );
            }
        }
        if !on(&p.enforce_admins) {
            note(
                &mut t,
                "enforce_admins",
                "GitHub let admins bypass this rule; bee land rules apply to everyone (use a ruleset with `bypass` to exempt admins)",
            );
        }
        if on(&p.allow_force_pushes) {
            note(
                &mut t,
                "allow_force_pushes",
                "protected refs move only through Land in bee; force updates need force_update on an unprotected ref",
            );
        }
        if on(&p.required_conversation_resolution) {
            note(
                &mut t,
                "required_conversation_resolution",
                "bee land rules do not require resolved threads",
            );
        }
        if p.required_deployments
            .as_ref()
            .is_some_and(|d| !d.is_empty())
        {
            note(
                &mut t,
                "required_deployments",
                "require the deployment workflows as checks instead",
            );
        }
        let block_delete = !on(&p.allow_deletions);
        let block_create = on(&p.block_creations);
        if block_delete || block_create {
            let _ = writeln!(refs_rules, "\n[[refs]]\npattern = {}", q(&pat));
            if block_create {
                let _ = writeln!(refs_rules, "create = []");
            }
            if block_delete {
                let _ = writeln!(refs_rules, "delete = []");
            }
        }
        t.translated.push(pattern.clone());
    }
    out.push_str(&refs_rules);
    // The parser is the judge: output it rejects is never handed out.
    if let Err(e) = bee_policy::parse_doc(&out, bee_policy::Origin::Repo) {
        t.untranslatable.push(Untranslatable {
            setting: "policy".into(),
            item: ".beehive/policy.toml".into(),
            detail: format!(
                "the generated policy did not validate ({e}); it was reduced to the version line"
            ),
        });
        out = "version = 1\n".into();
        t.skipped.append(&mut t.translated);
    }
    t.untranslatable.sort();
    t.toml = out;
    t
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::*;

    #[test]
    fn patterns() {
        assert_eq!(ref_pattern("main"), Some(("main".into(), false)));
        assert_eq!(ref_pattern("release/*"), Some(("release/*".into(), true)));
        assert_eq!(ref_pattern("*"), Some(("*".into(), false)));
        assert_eq!(ref_pattern("feat-[0-9]*"), None);
        assert_eq!(ref_pattern("**/x"), None);
        assert_eq!(ref_pattern("a*b"), None);
    }

    #[test]
    fn toml_strings_are_escaped() {
        assert_eq!(q("a\"b\\c\n"), "\"a\\\"b\\\\c\\n\"");
    }

    #[test]
    fn full_protection_translates_and_validates() {
        let mut p = BTreeMap::new();
        p.insert(
            "main".to_string(),
            Protection {
                required_status_checks: Some(StatusChecks {
                    strict: true,
                    contexts: vec!["ci/test".into()],
                    checks: vec![],
                }),
                required_pull_request_reviews: Some(ReviewRules {
                    required_approving_review_count: 2,
                    require_code_owner_reviews: true,
                    dismiss_stale_reviews: true,
                    require_last_push_approval: true,
                    ..Default::default()
                }),
                enforce_admins: Some(Enabled { enabled: true }),
                required_linear_history: Some(Enabled { enabled: true }),
                required_signatures: Some(Enabled { enabled: true }),
                restrictions: Some(Restrictions {
                    users: vec![User {
                        id: 5,
                        login: "alice".into(),
                        ..Default::default()
                    }],
                    teams: vec![Team {
                        slug: "core".into(),
                    }],
                    apps: vec![],
                }),
                ..Default::default()
            },
        );
        let mut dir = Directory::default();
        let t = translate(
            "acme/api",
            &p,
            Some((".github/CODEOWNERS", "* @acme/core\n")),
            &mut dir,
        );
        assert!(t.untranslatable.is_empty(), "{:?}", t.untranslatable);
        assert!(t.toml.contains("required_checks = [\"ci/test\"]"));
        assert!(t.toml.contains("from = \"owners\""));
        assert!(t.toml.contains("count = 2"));
        assert!(t.toml.contains("@acme/core"));
        assert!(t.toml.contains(&crate::principals::principal_id(5)));
        assert!(t.toml.contains("delete = []"));
        assert_eq!(t.codeowners_rules, 1);
        bee_policy::parse_doc(&t.toml, bee_policy::Origin::Repo).unwrap();
    }
}
